import codecs,hashlib,json,sys,unicodedata
assert sys.version_info[:3] == (3,14,7) and unicodedata.unidata_version == '16.0.0'
prefixes=[230,596,601,602,652,741,745,12363,12365,12367,12369,12371,12459,12461,12463,12465,12467,12475,12484,12488,12791]
def failure(e):
    return ['error',e.encoding,list(map(ord,e.object)),e.start,e.end,e.reason]
rows=[]
for prefix in prefixes:
    for block in range(8):
        h=hashlib.sha256()
        for suffix in range(block*8192,(block+1)*8192):
            source=chr(prefix)+chr(suffix)
            try: row=['ok',list(source.encode('shift_jisx0213'))]
            except UnicodeEncodeError as e: row=failure(e)
            h.update((json.dumps(row,separators=(',',':'),ensure_ascii=True)+'\n').encode())
        rows.append({'prefix':prefix,'block':block,'sha256':h.hexdigest()})
replay=[]
for prefix in prefixes:
    for suffix in [0,65,0x300,0x301,0x2e5,0x2e9,0x309a,0xd800,0x10000,0x20300,0x10ffff]:
        for errors in ['strict','ignore','replace']:
            for final in [False,True]:
                encoder=codecs.getincrementalencoder('shift_jisx0213')(errors)
                encoder.setstate(0x123456789abcdef000)
                calls=[]
                for source,flush in [(chr(prefix),False),(chr(suffix),final),('',True)]:
                    try: result=['ok',list(encoder.encode(source,flush))]
                    except UnicodeEncodeError as e: result=failure(e)
                    calls.append([result,str(encoder.getstate())])
                encoder.reset()
                replay.append({'prefix':prefix,'suffix':suffix,'errors':errors,'final':final,'calls':calls,'reset':str(encoder.getstate())})
print(json.dumps({'pairs':rows,'replay':replay}))
